    const now = current.get(p);
    if (!now) problems.push(`missing ${p}`);
    else if (JSON.stringify({ ...now, group: row.group }) !== JSON.stringify(row)) problems.push(`changed ${p}`);
  }
  for (const p of current.keys()) if (!expected.has(p)) problems.push(`unexpected ${p}`);
  process.stdout.write(JSON.stringify({ verified: expected.size, problems: problems.slice(0, 50), problemCount: problems.length }) + '\n');
  process.exitCode = problems.length ? 1 : 0;
} else {
  const entries = walk().map(r => ({ ...r, group: groupOf(r.path) }));
  const nodeBinary = process.execPath;
  const manifest = {
    schemaVersion: 1,
    standing: 'author-03 freeze candidate for root freezing and independent review; not an acceptance record',
    root: top,
    pinnedRuntime: { node: process.version, path: nodeBinary, sha256: sha256(fs.readFileSync(fs.realpathSync(nodeBinary))), systemTools: ['/usr/bin/tar (archive extraction)', '/usr/bin/time (real-lane measurement)'] },
    excluded: { scratch: EXCLUDED_DIRS.map(d => d + '/'), launcher: LAUNCHER.filter(f => fs.existsSync(path.join(top, f))) },
    counts: entries.reduce((acc, r) => ({ ...acc, [r.group]: (acc[r.group] ?? 0) + 1 }), {}),
    toolClosures: {
      checker: { ...closure('checker/node_modules', checkerPackages, archiveByKey), provisioning: 'byte copy of the four packages the checker executes from the frozen author02 npm closure (npm 11.13.0 --ignore-scripts); every package archive acquired and compared (provenance/archives, results/archive-verification.json)' },
      baseline: { ...closure('baseline/subject-02-trial/node_modules', Object.fromEntries(Object.entries(npmLock).filter(([k]) => k)), archiveByKey), provisioning: 'frozen author02 npm closure (44 packages); 5 archives acquired and compared, 39 verified only as frozen materialized bytes' },
      pnpmContractsLane: { ...closure('inputs/pnpm-provision-05/node_modules', { 'node_modules/.pnpm/typescript@6.0.3/node_modules/typescript': { version: '6.0.3', integrity: 'sha512-y2TvuxSZPDyQakkFRPZHKFm+KKVqIisdg9/CZwm9ftvKXLP8NRWj38/ODjNbr43SsoXqNuAisEf1GdCxqWcdBw==' } }, { 'node_modules/.pnpm/typescript@6.0.3/node_modules/typescript': archiveByKey['node_modules/typescript'] }), provisioning: 'pnpm 11.10.0 isolated linker, offline install record copied from m1-generator-typescript-provision-05; lane dependency closure, not the checker closure' },
    },
    entries,
  };
  manifest.aggregateSha256 = sha256(entries.map(r => `${r.type}\0${r.path}\0${r.mode}\0${r.bytes ?? ''}\0${r.sha256 ?? r.target ?? ''}`).join('\n'));
  fs.writeFileSync(path.join(top, OUTPUT), JSON.stringify(manifest, null, 2) + '\n');
  process.stdout.write(`${entries.length} entries ${JSON.stringify(manifest.counts)} aggregate ${manifest.aggregateSha256}\n`);
}

