404	function parseArguments(argv) {
405	  const usage = 'usage: check-boundary --root DIR --lane-record FILE --design-lock FILE --architecture DIR [--unbound-lane tooling]';
406	  const keys = ['--root', '--lane-record', '--design-lock', '--architecture', '--unbound-lane'];
407	  const values = {};
408	  for (let i = 0; i < argv.length; i += 2) {
409	    const [key, value] = [argv[i], argv[i + 1]];
410	    if (!keys.includes(key) || Object.hasOwn(values, key) || typeof value !== 'string' || !value || value.startsWith('--')) throw new LaneError(usage);
411	    values[key] = value;
412	  }
413	  for (const key of keys.slice(0, 4)) if (!values[key]) throw new LaneError(usage);
414	  return values;
415	}
