417	export async function main(argv) {
418	  try {
419	    const args = parseArguments(argv);
420	    let record;
421	    try { record = strictJson(fs.readFileSync(args['--lane-record']), 'lane record'); } catch (error) {
422	      throw error instanceof LaneError ? error : new LaneError('cannot read lane record: ' + error.message);
423	    }
424	    if (!fs.existsSync(args['--design-lock']) || !fs.statSync(args['--architecture'], { throwIfNoEntry: false })?.isDirectory()) throw new LaneError('design lock file and architecture directory must exist');
425	    const report = await checkBoundary({ root: args['--root'], record, designLock: args['--design-lock'], architecture: args['--architecture'], unboundKind: args['--unbound-lane'] });
426	    process.stdout.write(JSON.stringify(report, null, 2) + '\n');
427	    return report.passed ? 0 : 1;
428	  } catch (error) {
429	    process.stderr.write('boundary check refused: ' + error.message + '\n');
430	    return error instanceof LaneError ? 2 : 3;
431	  }
