function build(name, [file, from, to]) {
  const dir = path.join(work, name);
  fs.rmSync(dir, { recursive: true, force: true });
  fs.mkdirSync(dir, { recursive: true });
  fs.cpSync(path.join(top, 'checker/bin'), path.join(dir, 'bin'), { recursive: true });
  fs.cpSync(path.join(top, 'checker/src'), path.join(dir, 'src'), { recursive: true });
  fs.copyFileSync(path.join(top, 'checker/package.json'), path.join(dir, 'package.json'));
  fs.symlinkSync(path.relative(dir, path.join(top, 'checker/node_modules')), path.join(dir, 'node_modules'));
  const target = path.join(dir, file);
  const text = fs.readFileSync(target, 'utf8');
  if (text.split(from).length !== 2) throw new Error(`${name}: mutation site is not unique in ${file}`);
  fs.writeFileSync(target, text.replace(from, to));
  return path.join(dir, 'bin/check-boundary.mjs');
}

function run(name, bin) {
  return new Promise(resolve => {
    const started = Date.now();
    const child = spawn(process.execPath, ['--test', '--test-reporter=tap', path.join(top, 'checker/test/boundary.test.mjs')],
      { env: { ...process.env, TMPDIR: path.join(top, 'work', 'tmp'), OPENSIP_BOUNDARY_CHECKER: bin, OPENSIP_BOUNDARY_TEST_LABEL: 'mutant-' + name } });
    let tap = '';
    child.stdout.on('data', chunk => { tap += chunk; });
    child.stderr.on('data', chunk => { tap += chunk; });
    child.on('close', code => {
      const all = [...tap.matchAll(/^(\s*)not ok \d+ - (.*)$/gm)].map(m => ({ nested: m[1].length > 0, name: m[2] }));
      // Keep failing subtests; keep a failing top-level test only when none of its subtests failed.
      const failing = all.some(f => f.nested) ? all.filter(f => f.nested || !/^author, reviewer and regression cases/.test(f.name)).map(f => f.name) : all.map(f => f.name);
      resolve({ name, site: MUTANTS[name], exitCode: code, failing, survived: code === 0, seconds: Math.round((Date.now() - started) / 1000) });
    });
  });
}

fs.mkdirSync(resultsDir, { recursive: true });
const queue = Object.entries(MUTANTS).filter(([name]) => !only || only.test(name));
await Promise.all(Array.from({ length: concurrency }, async () => {
  while (queue.length) {
    const [name, site] = queue.shift();
    const outcome = await run(name, build(name, site));
    fs.writeFileSync(path.join(resultsDir, name + '.json'), JSON.stringify(outcome, null, 2) + '\n');
    process.stdout.write(`== ${name}: ${outcome.survived ? 'SURVIVED' : outcome.failing.length + ' failing'} (${outcome.seconds}s) ${outcome.failing.slice(0, 6).join(' | ')}\n`);
  }
}));
